BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Definition of a misstatement under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what constitutes a misstatement in the financial statements?', '["An error that exceeds performance materiality and requires adjustment by management", "A discrepancy between the financial statements and the prior-year comparative amounts", "A difference between the reported amount, classification, presentation, or disclosure and what is required by the applicable framework", "An intentional manipulation of financial data designed to deceive financial statement users"]'::jsonb, 2, 'Under AU-C 450.04, a misstatement is defined as a difference between the amount, classification, presentation, or disclosure of a reported financial statement item and what is required under the applicable financial reporting framework. Misstatements may arise from error or fraud. Choice A is incorrect because misstatements exist regardless of whether they exceed performance materiality; even clearly trivial amounts are technically misstatements.', 'easy', 1),

-- Q2: easy / L1 — Clearly trivial misstatement threshold
(1, 'Misstatements and Control Deficiencies', 'What does ''clearly trivial'' mean when evaluating identified misstatements under AU-C 450?', '["Amounts that are inconsequential both individually and in the aggregate", "Misstatements below 5% of performance materiality established for the engagement", "Errors that management has agreed to correct before the audit report date", "Differences that are smaller than the tolerable misstatement for any single account"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial misstatements are those the auditor designates as beneath a threshold where they would be inconsequential both individually and in the aggregate. The auditor is not required to accumulate clearly trivial amounts. Choice B is incorrect because AU-C 450 does not establish a specific numerical percentage for the clearly trivial threshold; rather, it requires professional judgment based on engagement circumstances.', 'easy', 1),

-- Q3: medium / L3 — Iron curtain vs rollover approach impact on evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Riverstone Electronics, the engagement team identifies $18,000 in uncorrected misstatements from the prior year that have not reversed, plus $22,000 in new current-year misstatements. Materiality is $35,000. How does the evaluation method affect the auditor''s conclusion about whether the financial statements are materially misstated?', '["Both the rollover and iron curtain approaches produce the same $40,000 aggregate, exceeding materiality under either method", "The rollover approach yields a $22,000 current-year impact below materiality, while the iron curtain approach yields a $40,000 cumulative balance-sheet effect exceeding materiality", "The iron curtain approach eliminates prior-year misstatements from consideration, resulting in only $22,000 under evaluation", "The rollover approach always produces a higher aggregate than the iron curtain approach when prior-year misstatements persist"]'::jsonb, 1, 'Under AU-C 450.A16, the rollover approach focuses on misstatements originating in the current period ($22,000), while the iron curtain approach considers the cumulative effect on the balance sheet ($40,000). Because the auditor should consider both approaches, the differing results here are significant—one exceeds materiality and the other does not. Choice A is incorrect because the two approaches intentionally produce different aggregates by design.', 'medium', 3),

-- Q4: medium / L2 — Accumulating misstatements above clearly trivial
(1, 'Misstatements and Control Deficiencies', 'While auditing Greystone Logistics, the engagement team identifies three misstatements: a $4,200 accounts payable understatement, a $2,800 revenue overstatement, and a $1,500 inventory understatement. The clearly trivial threshold is $1,000. Which misstatements must the auditor accumulate under AU-C 450?', '["Only the $4,200 accounts payable understatement because it is the largest individual misstatement", "The $4,200 and $2,800 misstatements because they exceed performance materiality individually", "Only the $2,800 revenue overstatement because it affects the income statement directly", "All three misstatements because each exceeds the clearly trivial threshold of $1,000"]'::jsonb, 3, 'Under AU-C 450.05, the auditor must accumulate all identified misstatements during the audit unless they are clearly trivial. Because each of the three misstatements ($4,200, $2,800, and $1,500) exceeds the $1,000 clearly trivial threshold, all three must be accumulated for evaluation. Choice A is incorrect because AU-C 450 requires accumulation of all non-trivial misstatements, not just the largest.', 'medium', 2),

-- Q5: hard / L3 — Effect of prior-year uncorrected misstatements on current year
(1, 'Misstatements and Control Deficiencies', 'Cascade Textiles had $28,000 in uncorrected misstatements from the prior year that understated depreciation expense. In the current year, the auditor sets materiality at $50,000 and identifies $19,000 in new current-year misstatements. The prior-year depreciation understatement has not reversed. What is the most likely effect on the current-year audit?', '["The prior-year misstatement is excluded from the current-year evaluation because it was accepted in the prior-year audit", "The prior-year misstatement reduces the current-year aggregate to $19,000 because depreciation errors self-correct over the asset''s life", "The cumulative uncorrected misstatement of $47,000 approaches materiality and requires the auditor to consider whether additional procedures or adjustment requests are necessary", "The auditor must issue a qualified opinion because the $47,000 aggregate exceeds performance materiality regardless of management''s response"]'::jsonb, 2, 'Under AU-C 450.11, the auditor must evaluate whether uncorrected misstatements—including those carried forward from prior periods—are material individually or in the aggregate. The cumulative $47,000 approaches the $50,000 materiality level, requiring the auditor to reassess risk and potentially request correction. Choice A is incorrect because AU-C 450 explicitly requires prior-year uncorrected misstatements to be considered in the current-year evaluation.', 'hard', 3),

-- Q6: medium / L2 — Design deficiency vs operating deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bridgeport Manufacturing, the auditor discovers that the company has a documented policy requiring supervisory approval for all journal entries over $5,000. However, the supervisor has been approving entries without reviewing the supporting documentation. Under AU-C 265, how should the auditor classify this finding?', '["A design deficiency because the control policy fails to address the risk of unauthorized entries", "An operating deficiency because the control is properly designed but not operating effectively as intended", "A compliance deficiency because the supervisor is violating company policy rather than a control failing", "A monitoring deficiency because the company failed to detect the supervisor''s noncompliance"]'::jsonb, 1, 'Under AU-C 265.A1, an operating deficiency exists when a properly designed control does not operate effectively or when the person performing the control lacks the competence to do so. The policy requiring supervisory approval is adequately designed, but the supervisor''s rubber-stamping without review means it is not operating as intended. Choice A is incorrect because the control''s design—requiring supervisory approval over $5,000—appropriately addresses the risk; the failure is in execution.', 'medium', 2),

-- Q7: easy / L1 — Summary of uncorrected misstatements documentation
(1, 'Misstatements and Control Deficiencies', 'What document does the auditor prepare to track all identified misstatements during an audit engagement?', '["A control deficiency letter addressed to management and those charged with governance", "A materiality memorandum that sets quantitative thresholds for the engagement", "A management representation letter listing all corrected financial statement errors", "A summary of uncorrected misstatements communicated to those charged with governance"]'::jsonb, 3, 'Under AU-C 450.12, the auditor must communicate uncorrected misstatements to those charged with governance via a summary that includes the individual amounts. This summary serves as the working paper tracking all accumulated misstatements during the engagement. Choice A is incorrect because the control deficiency letter addresses internal control findings under AU-C 265, not the accumulation of financial statement misstatements.', 'easy', 1),

-- Q8: medium / L3 — Control environment weakness elevates deficiency severity
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinnacle Distribution, the auditor finds that individual control deficiencies in cash disbursements are each rated as deficiencies when considered alone. However, the auditor also observes that the company''s tone at the top is weak and the board provides minimal oversight of financial reporting. What is the most likely effect of the control environment on the auditor''s evaluation of these deficiencies?', '["The weak control environment may elevate the severity of the individual deficiencies because entity-level controls affect the effectiveness of process-level controls", "The weak control environment has no effect because each deficiency must be evaluated independently based on its own likelihood and magnitude", "The weak control environment automatically converts all identified deficiencies into material weaknesses requiring immediate disclosure", "The weak control environment only affects the auditor''s risk assessment and has no bearing on the classification of control deficiencies"]'::jsonb, 0, 'Under AU-C 265.A14, the auditor considers entity-level controls—including the control environment—when evaluating the severity of deficiencies. A weak tone at the top or ineffective board oversight can increase the likelihood that process-level deficiencies will result in material misstatements, elevating their severity. Choice B is incorrect because AU-C 265 explicitly requires the auditor to consider the broader control environment when assessing individual deficiency severity.', 'medium', 3),

-- Q9: hard / L4 — Evaluate whether misstatements are pervasive for opinion determination
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Capital Group, the auditor identifies $95,000 in uncorrected misstatements spread across accounts receivable, revenue, and inventory—all linked to the same flawed cutoff procedure. Overall materiality is $80,000. Management declines to make corrections. The auditor must determine whether to issue a qualified opinion or an adverse opinion. What is the most important factor in this determination?', '["Whether the $95,000 aggregate exceeds twice the overall materiality threshold, which is the standard benchmark for pervasiveness", "Whether management provided a valid business reason for declining to correct the identified misstatements", "Whether the misstatements are pervasive to the financial statements, meaning they affect multiple elements, accounts, or disclosures and are not confined to specific items", "Whether the prior-year audit opinion was unmodified, which would support maintaining a qualified rather than adverse opinion"]'::jsonb, 2, 'Under AU-C 705.08, when misstatements are material, the auditor distinguishes between a qualified opinion (material but not pervasive) and an adverse opinion (material and pervasive). Pervasiveness depends on whether the misstatements affect numerous accounts, represent a substantial portion of the financial statements, or fundamentally undermine disclosures. Choice A is incorrect because AU-C 705 does not establish a numerical multiplier of materiality as the benchmark for pervasiveness; rather, it requires judgment about breadth of impact.', 'hard', 4),

-- Q10: hard / L4 — Recommend response when misstatement indicates management override
(1, 'Misstatements and Control Deficiencies', 'While auditing Lakewood Retail, the engagement team discovers a $12,000 misstatement caused by an intentional override of the revenue cutoff control by the division controller. Materiality is $200,000 and the amount is quantitatively immaterial. The auditor must evaluate the appropriate response. What should the auditor recommend?', '["Treat the misstatement as clearly trivial because $12,000 is well below the $200,000 materiality threshold and document it accordingly", "Evaluate the misstatement qualitatively because intentional misstatements, even if quantitatively immaterial, may indicate fraud risk factors that affect the overall audit approach", "Immediately withdraw from the engagement because intentional management override of controls constitutes a breach of the auditor-client relationship", "Reclassify the misstatement from a factual misstatement to a projected misstatement to reflect the potential for additional undetected overrides"]'::jsonb, 1, 'Under AU-C 450.A22, the auditor must consider the qualitative nature of misstatements, including whether they result from intentional acts. An intentional override, even if quantitatively small, may indicate fraud under AU-C 240 and could signal broader management integrity concerns requiring expanded procedures. Choice A is incorrect because AU-C 450 prohibits treating intentional misstatements as trivial solely based on their dollar amount; the qualitative nature is a critical consideration.', 'hard', 4),

-- Q11: medium / L3 — Effect of misstatement nature on planned procedures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornfield Enterprises, the auditor identifies a $6,000 misstatement in prepaid insurance caused by a clerical transposition error. The clearly trivial threshold is $2,000 and performance materiality is $30,000. What is the most likely effect of this misstatement on the auditor''s planned procedures?', '["The auditor must expand substantive testing in all accounts because any misstatement above the clearly trivial threshold indicates pervasive control failures", "The auditor should immediately communicate the transposition error to those charged with governance as a significant deficiency", "The auditor must lower overall materiality by the $6,000 misstatement amount to maintain an appropriate margin for undetected errors", "The auditor accumulates the misstatement and considers whether its nature, cause, or pattern suggests additional misstatements may exist in similar accounts"]'::jsonb, 3, 'Under AU-C 450.06, the auditor evaluates each identified misstatement to determine whether the audit strategy needs revision. A clerical error in one account may indicate similar errors in other accounts processed by the same individual or system, and the auditor should assess whether additional procedures are warranted. Choice A is incorrect because a single clerical error does not necessarily indicate pervasive control failures requiring expansion of all substantive testing.', 'medium', 3),

-- Q12: medium / L2 — Communication timing for control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Ashford & Partners is performing the December 31, 2025 audit of Crestline Hospitality. In February 2026, the engagement team identifies a material weakness in payroll processing controls. The audit report is expected to be issued on March 15, 2026. Under AU-C 265, when must the auditor communicate this material weakness in writing?', '["No later than 60 days following the audit report release date of March 15, 2026", "Immediately upon discovery in February 2026 before completing any additional audit procedures", "Within 30 days of identifying the material weakness but before issuing the audit report", "By December 31, 2025, to coincide with the fiscal year-end under audit"]'::jsonb, 0, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the release date of the auditor''s report. This allows the auditor to complete the evaluation before formal communication. Choice B is incorrect because AU-C 265 does not require immediate written communication upon discovery; the auditor is permitted to finalize the evaluation within the specified timeframe.', 'medium', 2),

-- Q13: medium / L3 — Recurring control deficiency implications
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northwind Logistics, the auditor identifies the same bank reconciliation control deficiency for the third consecutive year. Management has acknowledged the deficiency each year but has not implemented corrective action. What is the most likely implication of this recurring pattern for the auditor''s current-year evaluation?', '["The recurring nature has no effect on classification because severity is based solely on the current-year likelihood and magnitude", "The auditor must report the recurring deficiency to a regulatory authority because three consecutive years of noncorrection indicates willful negligence", "The recurring pattern may indicate a weakness in the monitoring component of internal control, potentially elevating the deficiency''s severity classification", "The auditor should remove the deficiency from the current-year communication because it was previously communicated and management is aware"]'::jsonb, 2, 'Under AU-C 265.A8, the auditor considers whether recurring deficiencies indicate a broader monitoring failure within the entity''s internal control system. A deficiency that persists over multiple years without correction suggests the monitoring component is not functioning effectively, which may elevate overall severity. Choice A is incorrect because AU-C 265 requires the auditor to consider the control environment and monitoring components, meaning recurring patterns are relevant to severity classification.', 'medium', 3),

-- Q14: medium / L3 — Qualitative factors in misstatement evaluation near covenant
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bellingham Industries, the auditor identifies a $3,500 misstatement that understated executive bonus accruals. Materiality is $150,000. The misstatement involves management compensation and relates to a debt covenant requiring minimum net income of $2 million. Net income before the misstatement is $2,002,000. What factor most significantly affects the auditor''s evaluation?', '["The $3,500 amount is clearly trivial relative to the $150,000 materiality level and requires no further evaluation", "The misstatement''s proximity to the debt covenant threshold makes it qualitatively significant despite its small dollar amount", "The misstatement relates to executive compensation, which is always classified as material regardless of the amount involved", "The misstatement must be evaluated against performance materiality rather than overall materiality for proper classification"]'::jsonb, 1, 'Under AU-C 450.A22, the auditor considers qualitative factors when evaluating misstatements, including whether they affect compliance with loan covenants or regulatory requirements. A $3,500 understatement that could cause a net income covenant violation is qualitatively significant regardless of its size relative to materiality. Choice A is incorrect because AU-C 450 explicitly prohibits dismissing misstatements as trivial when qualitative factors—such as covenant proximity—make them significant.', 'medium', 3),

-- Q15: easy / L1 — Indicators of a material weakness
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which of the following is a strong indicator that a material weakness exists in internal control?', '["Identification of fraud committed by senior management, regardless of the dollar amount involved", "Discovery of a single clerical error that was promptly detected and corrected by the entity", "A control deficiency that has existed for less than one fiscal quarter before being remediated", "An immaterial misstatement identified by the auditor during routine substantive testing"]'::jsonb, 0, 'Under AU-C 265.A12, fraud by senior management is a strong indicator of a material weakness because it demonstrates a failure in the control environment, specifically in management integrity and ethical values. Even small-dollar fraud by senior management raises fundamental concerns about financial reporting reliability. Choice B is incorrect because a promptly detected and corrected clerical error typically indicates that controls are operating effectively rather than deficiently.', 'easy', 1),

-- Q16: medium / L2 — Projecting sample misstatements to the population
(1, 'Misstatements and Control Deficiencies', 'The auditor of Palmer Pharmaceuticals selects a sample of 60 revenue transactions from a population of 4,500 transactions totaling $9.8 million. The sample reveals $7,200 in misstatements. Performance materiality for revenue is $45,000. Under AU-C 530, what must the auditor do to determine the effect on the revenue account?', '["Compare the $7,200 sample misstatement directly to the $45,000 performance materiality to assess whether revenue is materially misstated", "Divide $7,200 by 60 to determine an average misstatement per item and multiply by the remaining untested population only", "Accept the revenue balance as fairly stated because $7,200 is less than 1% of the $9.8 million population", "Project the $7,200 sample misstatement to the full population and compare the projected amount to tolerable misstatement"]'::jsonb, 3, 'Under AU-C 530.13, when misstatements are found in a sample, the auditor must project the misstatement to the population and evaluate the projected amount against tolerable misstatement for that account. The raw sample misstatement alone does not indicate the population''s likely total error. Choice A is incorrect because comparing the unadjusted sample misstatement to performance materiality without projection fails to account for undetected misstatements in the untested portion.', 'medium', 2),

-- Q17: hard / L4 — Evaluate competing positions on misstatement correction near materiality
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Manufacturing, the auditor identifies $42,000 in uncorrected misstatements with materiality at $50,000. Management argues the misstatements are immaterial and declines correction. The engagement partner notes that projected misstatements from sampling have a $15,000 estimation uncertainty range. The audit committee asks for a recommendation. What is the best course of action?', '["Request management to correct the misstatements because the $42,000 aggregate plus sampling uncertainty could exceed materiality, making the margin of safety insufficient", "Accept management''s position because $42,000 is below the $50,000 materiality threshold and the auditor should defer to management on correction decisions", "Issue a qualified opinion immediately because uncorrected misstatements within 85% of materiality automatically require opinion modification", "Reduce materiality to $35,000 to create a sufficient buffer and then reassess whether the misstatements are material under the revised threshold"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements considering both known amounts and the risk that undetected misstatements plus projection uncertainty could push the aggregate above materiality. With only $8,000 of headroom and $15,000 in estimation uncertainty, requesting correction is prudent. Choice B is incorrect because AU-C 450 requires the auditor to exercise independent judgment rather than deferring to management''s materiality assessment.', 'hard', 4),

-- Q18: medium / L2 — Management representations about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Summerfield Distributing, the auditor communicates a summary of $14,000 in uncorrected misstatements to management and those charged with governance. Management declines to correct the misstatements. Under AU-C 580, what must the auditor obtain from management?', '["A signed acknowledgment that the uncorrected misstatements will be corrected in the subsequent fiscal year", "An independent third-party valuation confirming that the uncorrected amounts are below the clearly trivial threshold", "A written representation that management believes the effects of uncorrected misstatements are immaterial to the financial statements", "A verbal confirmation recorded in the audit workpapers that management understands the misstatements exist"]'::jsonb, 2, 'Under AU-C 580.11, the auditor must obtain written representations from management that it believes the effects of uncorrected misstatements aggregated by the auditor are immaterial, both individually and in the aggregate, to the financial statements as a whole. Choice D is incorrect because AU-C 580 specifically requires written—not verbal—representations, and the representation must address management''s belief about the immateriality of the uncorrected amounts.', 'medium', 2),

-- Q19: medium / L2 — Entity-level vs process-level control deficiency classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Highland Construction, the auditor discovers that the company''s code of conduct has not been updated in five years, the ethics hotline is nonfunctional, and no fraud risk assessment has been performed. Under AU-C 315, these findings relate to which category of internal control?', '["Process-level transaction controls because they affect the day-to-day processing of construction contracts", "Entity-level controls within the control environment component because they involve governance, ethics, and risk oversight", "Information technology general controls because they relate to the infrastructure supporting financial reporting", "Monitoring controls because they involve reviewing the effectiveness of other internal controls over time"]'::jsonb, 1, 'Under AU-C 315.14, the control environment sets the tone of the organization and encompasses integrity, ethical values, and governance oversight. An outdated code of conduct, nonfunctional ethics hotline, and absent fraud risk assessment are entity-level control environment deficiencies. Choice D is incorrect because monitoring controls involve evaluating whether existing controls are operating as designed, whereas these findings relate to the foundational control environment components.', 'medium', 2),

-- Q20: easy / L1 — Auditor's required initial action upon identifying misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the auditor''s required initial action upon identifying misstatements during the audit?', '["Report each misstatement immediately to those charged with governance in a formal written communication", "Withdraw from the engagement if management does not agree to correct all identified misstatements", "Modify the audit opinion for each identified misstatement that exceeds the clearly trivial threshold", "Communicate all accumulated misstatements to the appropriate level of management and request correction"]'::jsonb, 3, 'Under AU-C 450.08, the auditor must communicate all misstatements accumulated during the audit to the appropriate level of management on a timely basis and request that management correct them. This is the auditor''s initial required action. Choice A is incorrect because AU-C 450 requires communication to management first; communication to those charged with governance for uncorrected misstatements is a subsequent step.', 'easy', 1),

-- Q21: medium / L3 — Restatement as indicator of material weakness
(1, 'Misstatements and Control Deficiencies', 'While auditing Westbrook Financial, the auditor discovers that a prior-period error required restatement of the comparative financial statements. The error resulted from a revenue recognition control that failed to apply cutoff procedures properly. What is the most likely effect on the auditor''s current-year control deficiency evaluation?', '["The restatement is a strong indicator of a material weakness because the control failure resulted in materially misstated financial statements that were previously issued", "The restatement has no effect on the current-year evaluation because control deficiencies are assessed only for the period under audit", "The restatement automatically downgrades all revenue recognition controls to significant deficiencies for the current year", "The restatement requires the auditor to communicate a material weakness only if the same control failure continues in the current year"]'::jsonb, 0, 'Under AU-C 265.A12, restatement of previously issued financial statements to correct a material misstatement is a strong indicator of a material weakness. The control failure that caused the restatement demonstrates that internal controls did not prevent or detect a material error before issuance. Choice D is incorrect because the indicator applies regardless of whether the specific control failure persists; the fact that it occurred and resulted in restatement is itself the basis for classification.', 'medium', 3),

-- Q22: easy / L1 — Deficiency severity hierarchy under AU-C 265
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, how are internal control deficiencies categorized from least severe to most severe?', '["Reportable condition, significant deficiency, material weakness", "Immaterial weakness, moderate deficiency, material weakness", "Deficiency, significant deficiency, material weakness", "Minor deficiency, major deficiency, critical deficiency"]'::jsonb, 2, 'Under AU-C 265.07, internal control deficiencies are categorized into three levels: a deficiency (least severe), a significant deficiency (important enough to merit attention by those charged with governance), and a material weakness (most severe). Choice A is incorrect because "reportable condition" is an outdated term from SAS 60 that was replaced by the current AU-C 265 hierarchy of deficiency, significant deficiency, and material weakness.', 'easy', 1),

-- Q23: easy / L2 — Classifying a segregation of duties finding
(1, 'Misstatements and Control Deficiencies', 'During the audit of Elm Street Bakery, the auditor finds that the bookkeeper both records vendor invoices and signs checks without secondary approval. The bookkeeper has been with the company for 15 years without incident. Under AU-C 265, how should the auditor classify this finding?', '["Not a deficiency because the bookkeeper''s long tenure and clean record demonstrate effective control", "A deficiency or higher because the lack of segregation of duties creates a reasonable possibility that a misstatement could occur undetected", "A management advisory comment because segregation of duties is a best practice recommendation rather than a required control", "A compliance finding because the bookkeeper''s dual role violates federal regulations on financial reporting"]'::jsonb, 1, 'Under AU-C 265.A1, a control deficiency exists when the design or operation of a control does not allow management or employees to prevent, or detect and correct, misstatements on a timely basis. Inadequate segregation of duties represents at minimum a deficiency regardless of the individual''s history. Choice A is incorrect because an individual''s clean record does not compensate for the design deficiency of having incompatible duties performed by one person.', 'easy', 2),

-- Q24: medium / L2 — Timely interim communication of material weakness
(1, 'Misstatements and Control Deficiencies', 'Martinez & Associates is auditing Silverline Technologies for the year ended December 31, 2025. During interim fieldwork in October 2025, the engagement team identifies what appears to be a material weakness in revenue recognition controls. The final audit report is not expected until March 2026. Under AU-C 265, what should the auditor do?', '["Communicate the potential material weakness to management and those charged with governance on a timely basis rather than waiting until audit completion", "Withhold communication until audit completion in March 2026 to ensure the evaluation is final before reporting", "Issue a preliminary written communication in October 2025 that is superseded by the final communication in March 2026", "Communicate the finding to management only and defer governance communication until the 60-day post-report window"]'::jsonb, 0, 'Under AU-C 265.12, the auditor should communicate significant deficiencies and material weaknesses to those charged with governance on a timely basis. When a material weakness is identified during interim fieldwork, waiting until audit completion could delay corrective action unnecessarily. Choice B is incorrect because AU-C 265 emphasizes timely communication, meaning the auditor should not wait months to inform governance of a material weakness that could be addressed sooner.', 'medium', 2),

-- Q25: hard / L4 — Assess combined effect of individually insignificant deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Coastal Marine Suppliers, the auditor identifies five separate control deficiencies: no review of journal entries under $10,000, lack of physical inventory count oversight, the accounts receivable clerk also approves credit memos, no formal IT access review process, and bank reconciliations prepared but never reviewed. Each deficiency individually is classified below significant deficiency. The auditor must assess the combined effect. What is the best approach?', '["Report all five deficiencies individually in the management letter because deficiencies not individually significant cannot be aggregated", "Select the two most severe deficiencies for governance communication and classify the remaining three as advisory comments", "Calculate a dollar amount for each deficiency and aggregate the totals to determine whether the combined amount exceeds materiality", "Evaluate whether the combination creates a reasonable possibility that a material misstatement would not be prevented or detected, which would constitute a significant deficiency or material weakness"]'::jsonb, 3, 'Under AU-C 265.A8, the auditor must consider whether individually insignificant deficiencies, in combination, represent a significant deficiency or material weakness. The evaluation focuses on whether combined control failures create a reasonable possibility of undetected material misstatement rather than aggregating dollar amounts. Choice C is incorrect because control deficiency severity is assessed based on likelihood and magnitude of potential misstatement, not by summing hypothetical dollar values across unrelated deficiencies.', 'hard', 4),

-- Q26: medium / L2 — Corrected vs uncorrected misstatement classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Shipping, the auditor identifies a $9,000 inventory overstatement that management recorded as an adjusting entry before year-end. The auditor also identifies a $5,000 depreciation understatement that management acknowledges but did not record. Under AU-C 450, how should the auditor categorize these misstatements?', '["Both are classified as corrected misstatements because management has acknowledged their existence", "The $9,000 is an uncorrected misstatement and the $5,000 is a corrected misstatement because only the larger amount requires tracking", "The $9,000 is a corrected misstatement because it was adjusted in the books, and the $5,000 is an uncorrected misstatement because the entry was not recorded", "Both are classified as uncorrected misstatements until the auditor verifies they are reflected in the final trial balance"]'::jsonb, 2, 'Under AU-C 450.05, misstatements that management corrects by posting to the accounting records are tracked separately from those that remain uncorrected. The $9,000 inventory adjustment was posted and is therefore corrected, while the $5,000 depreciation understatement remains unrecorded and uncorrected. Choice A is incorrect because merely acknowledging a misstatement does not constitute correction; the adjustment must be recorded in the accounting records.', 'medium', 2),

-- Q27: hard / L4 — Evaluate systemic misstatements with narrow margin to materiality
(1, 'Misstatements and Control Deficiencies', 'While auditing Pacific Ridge Electronics, the engagement team identifies 14 misstatements across six accounts, all caused by an incorrectly configured ERP allocation module after a mid-year system upgrade. Individual misstatements range from $2,000 to $11,000 with an aggregate of $64,000 against materiality of $75,000. Management corrects the ERP configuration but declines to adjust the historical entries. What should the auditor recommend?', '["Accept management''s position because the root cause has been corrected and future periods will not be affected", "Evaluate whether the systemic nature, common root cause, and narrow margin to materiality collectively warrant requesting correction of the historical entries or modifying the opinion", "Issue an adverse opinion because 14 misstatements across six accounts demonstrates pervasive control failure regardless of dollar amount", "Communicate the ERP configuration issue as a significant deficiency but accept the financial statements without modification since the aggregate is below materiality"]'::jsonb, 1, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements considering both quantitative and qualitative factors. Fourteen misstatements from a systemic root cause across six accounts, totaling 85% of materiality, indicate elevated risk that additional undetected misstatements may exist. The narrow margin and systemic nature support requesting correction. Choice A is incorrect because correcting the root cause prospectively does not eliminate the need to evaluate the historical financial statement impact.', 'hard', 4),

-- Q28: easy / L1 — Restricted use of control deficiency communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, why is the written communication of control deficiencies restricted to management and those charged with governance?', '["Because the communication is intended solely for parties responsible for internal control oversight and could be misunderstood by others", "Because auditing standards prohibit any discussion of internal control findings with parties outside the audit engagement", "Because control deficiency communications contain confidential pricing information about the audit engagement", "Because the auditor''s professional liability coverage only applies to communications made to management and governance"]'::jsonb, 0, 'Under AU-C 265.14, the written communication includes a statement that it is intended solely for the information and use of management, those charged with governance, and others within the organization. This restriction exists because external parties may misinterpret the significance of the findings. Choice B is incorrect because AU-C 265 does not prohibit all external discussion; rather, it restricts the intended audience of the formal written communication.', 'easy', 1),

-- Q29: easy / L1 — Definition of materiality for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what determines whether an identified misstatement is considered material?', '["Whether the misstatement was caused by an intentional act of fraud or an unintentional clerical error", "Whether the misstatement was identified during interim fieldwork or final year-end testing procedures", "Whether the misstatement affects a balance sheet account or an income statement account", "Whether the misstatement, individually or aggregated with others, could reasonably influence economic decisions of financial statement users"]'::jsonb, 3, 'Under AU-C 320.02, materiality is based on whether misstatements could reasonably be expected to influence the economic decisions of users taken on the basis of the financial statements. The determination involves both quantitative size and qualitative considerations. Choice A is incorrect because while causation (fraud vs. error) affects the auditor''s response under AU-C 240, materiality itself is defined by the potential influence on user decisions, not by how the misstatement arose.', 'easy', 1),

-- Q30: medium / L3 — Analyzing effect of identified misstatement on further procedures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westgate Pharmaceuticals, the auditor discovers a $25,000 revenue cutoff error in December 2025 resulting from a shipment recorded before title transferred to the customer. Performance materiality is $40,000. The same sales clerk processed approximately 200 December transactions. What is the most likely effect on the auditor''s planned procedures?', '["The auditor should accept the misstatement as isolated because a single error in 200 transactions represents less than a 1% error rate", "The auditor should consider expanding cutoff testing for other December transactions processed by the same clerk because the error may indicate a systematic processing issue", "The auditor should immediately communicate the cutoff error to those charged with governance before performing any additional testing", "The auditor should recalculate overall materiality to exclude December revenue transactions from the financial statement base"]'::jsonb, 1, 'Under AU-C 450.06, when the auditor identifies a misstatement, the auditor considers whether the nature and cause suggest additional misstatements may exist. A cutoff error linked to a specific clerk who processed many similar transactions suggests a potential systematic pattern warranting expanded testing of that population. Choice A is incorrect because AU-C 450 requires evaluating the implications of the misstatement''s cause rather than simply calculating an error rate and dismissing it as isolated.', 'medium', 3)
;

COMMIT;
